      SUBROUTINE DEPENDCC     TEST FOR ALGEBRAIC DEPENDENCECC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM22A.CIN'      INCLUDE 'ELM23.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'IOUNIT.CIN'CC     LOCAL VARIABLESC      REAL            DREGA(NPVAR), DREGB(NPVAR), DREGC(NPVAR)      EXTERNAL        IDATACC-----------------------------------------------------------------CC     INPUT REGISTERS AND OPERATIONC      K1 = K1REG      K2 = K2REG      J = JREG      NP1 = NV1 + 1      IF (JTIE .EQ. 0 .AND. J .GT. 20) GO TO 500      IF (K1TIE .EQ. 0 .AND. K1 .GT. 20) GO TO 500CC     FIRST OPERANDC      IF (K1TIE .EQ. 100) GO TO 20      IF (.NOT. LREG(K1)) GO TO 500      IF (NV3 .EQ. 0) GO TO 50      DO 5 JJ = 1, NV1    5 DREGA(JJ) = DREG(K1,JJ)      IF (NV1 .GE. NPVAR) GO TO 50   10 DO 15 JJ = NP1, NPVAR   15 DREGA(JJ) = 0.0      GO TO 50C   20 IF (NV3 .EQ. 0) GO TO 50      DO 25 JJ = 1, NV3   25 DREGA(JJ) = 0.0   26 NV2 = TIE(K1)      IF (NV2 .EQ. 100) THEN        K1 = IDATA(K1)        GO TO 26      ENDIF      IF (NV2 .EQ. 0) GO TO 50      IF (NV2 .EQ. 99) GO TO 30      IF (NV2 .LT. 0 .OR. NV2 .GT. NPVAR) THEN        WRITE (NOUT,9005) NV2 9005   FORMAT (' *** ERROR ***, NV2 = ',I5)        FLUSHL = .TRUE.        GO TO 550      ENDIF      DREGA(NV2) = 1.0      GO TO 50C   30 IF (NV3 .EQ. 0) GO TO 50      DO 35 JJ = 1, NV1   35 DREGA(JJ) = DATA(K1+JJ)CC     SECOND OPERANDC   50 IF (IOPN .GT. 4) GO TO 100      IF (K2TIE .EQ. 0 .AND. K2 .GT. 20) GO TO 500      IF (K2TIE .EQ. 100) GO TO 70      IF (.NOT. LREG(K2)) GO TO 500      IF (NV3 .EQ. 0) GO TO 100      DO 55 JJ = 1, NV1   55 DREGB(JJ) = DREG(K2,JJ)      IF (NV1 .GE. NPVAR) GO TO 100   60 DO 65 JJ = NP1, NPVAR   65 DREGB(JJ) = 0.0      GO TO 100C   70 IF (NV3 .EQ. 0) GO TO 100      DO 75 JJ = 1, NV3   75 DREGB(JJ) = 0.0   76 NV2 = TIE(K2)      IF (NV2 .EQ. 100) THEN        K2 = IDATA(K2)        GO TO 76      ENDIF      IF (NV2 .EQ. 0) GO TO 100      IF (NV2 .EQ. 99) GO TO 80      IF (NV2 .LT. 0 .OR. NV2 .GT. NPVAR) THEN        WRITE (NOUT,9005) NV2        FLUSHL = .TRUE.        GO TO 550      ENDIF      DREGB(NV2) = 1.0      GO TO 100C   80 IF (NV3 .EQ. 0) GO TO 100      DO 85 JJ = 1, NV1   85 DREGB(JJ) = DATA(K2+JJ)CC     OPERATIONSC  100 IF (NV3 .EQ. 0) GO TO 106      IF (NV3 .GE. NPVAR) GO TO 106      DO 105 JJ = NP1, NPVAR  105 DREGC(JJ) = 0.0  106 IF (IOPN .LT. 10) THEN        GO TO 110      ELSE        GO TO 150      ENDIFCC     BINARY OPERATIONSC  110 IF (NV3 .EQ. 0) GO TO 500      DO 115 N = 1, NV1      IF (DREGA(N) .GT. 0.5 .OR. DREGB(N) .GT. 0.5) DREGC(N) = 1.0  115 CONTINUE      GO TO 500CC     UNARY OPERATIONSC  150 IF (NV3 .EQ. 0) GO TO 500      DO 155 N = 1, NV1      IF (DREGA(N) .GT. 0.5) DREGC(N) = 1.0  155 CONTINUE      GO TO 500CC     STORE RESULT OF OPERATIONC  500 IF (JTIE .EQ. 100) GO TO 520      LREG(J) = .TRUE.      IF (NV3 .EQ. 0) GO TO 550      DO 505 JJ = 1, NV1  505 DREG(J,JJ) = DREGC(JJ)      GO TO 550C  520 IF (NV3 .EQ. 0) GO TO 550      DO 525 JJ = 1, NV1      DATA(J+JJ) = DREGC(JJ)  525 CONTINUEC  550 RETURN      END